 static int Depth(Transform t){int d=0;for(var p=t.parent;p;p=p.parent)d++;return d;}
 static float RestoreBind(SkinnedMeshRenderer skin){var b=skin.bones;var matrices=skin.sharedMesh.bindposes.Select(m=>skin.transform.localToWorldMatrix*m.inverse).ToArray();if(b.Length!=matrices.Length)throw new Exception("Bind count");foreach(int i in Enumerable.Range(0,b.Length).OrderBy(i=>Depth(b[i])))b[i].SetPositionAndRotation(matrices[i].GetColumn(3),matrices[i].rotation);float max=0;for(int i=0;i<b.Length;i++)max=Math.Max(max,Vector3.Distance(b[i].position,matrices[i].GetColumn(3)));if(max>1e-5f)throw new Exception("True bind restoration mismatch "+max);return max;}
 static Quaternion Basis(Transform[] b){var up=(b[5].position-b[0].position).normalized;var right=(b[18].position-b[14].position).normalized;return Quaternion.LookRotation(Vector3.Cross(right,up).normalized,up);}
 static float Height(Transform[] b){return Vector3.Dot(b[0].position-(b[16].position+b[20].position)*.5f,Basis(b)*Vector3.up);}
 static string Hash(string p){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
