 static float Angle(Vector3 a,Vector3 b){double x=(double)a.y*b.z-(double)a.z*b.y,y=(double)a.z*b.x-(double)a.x*b.z,z=(double)a.x*b.y-(double)a.y*b.x,dot=(double)a.x*b.x+(double)a.y*b.y+(double)a.z*b.z;return (float)(Math.Atan2(Math.Sqrt(x*x+y*y+z*z),dot)*180/Math.PI);}
 public void Sample(float seconds){sourceBind.Restore();clip.SampleAnimation(source,Mathf.Clamp(seconds,0,clip.length));targetCanonical.Restore();Vector3 hip=targetHip+alignment*(sb[0].position-sourceHip)*ratio;Vector3 up=BasisFromBindUp();hip=targetHip+Vector3.Project(hip-targetHip,up);tb[0].position=hip;Quaternion inverse=Quaternion.Inverse(alignment);for(int b=0;b<tb.Length;b++)tb[b].rotation=alignment*(sb[b].rotation*Quaternion.Inverse(sourceT[b]))*inverse*targetT[b];
