 lastArmTwistProof=null;string armGainString=Environment.GetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_GAIN");float armGain=string.IsNullOrEmpty(armGainString)?1:float.Parse(armGainString,System.Globalization.CultureInfo.InvariantCulture);if(armGain<0||armGain>1)throw new Exception("Invalid arm twist gain");string fadeString=Environment.GetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_FADE_SECONDS");float fade=string.IsNullOrEmpty(fadeString)?0:float.Parse(fadeString,System.Globalization.CultureInfo.InvariantCulture);if(fade<0||fade>1)throw new Exception("Invalid twist fade");if(fade>0){float weight=Mathf.SmoothStep(0,1,Mathf.Clamp01(seconds/fade))*Mathf.SmoothStep(0,1,Mathf.Clamp01((clip.length-seconds)/fade));armGain=1-(1-armGain)*weight;}effectiveArmTwistGain=armGain;
 if(armGain<1){lastArmTwistProof=new List<ArmTwistProof>();foreach(int i in new[]{7,11}){var delta=Quaternion.Inverse(canonicalLocal[i])*tb[i].localRotation;float angle=TwistAngle(delta,targetAxis[i],out bool singular);if(singular)throw new Exception("Undefined upper-arm twist");var swing=delta*Quaternion.Inverse(Quaternion.AngleAxis(angle,targetAxis[i]));var elbow=tb[i+1].position;var hand=tb[i+2].position;var forearmWorld=tb[i+1].rotation;tb[i].localRotation=canonicalLocal[i]*swing*Quaternion.AngleAxis(angle*armGain,targetAxis[i]);tb[i+1].rotation=forearmWorld;var proof=new ArmTwistProof{bone=TargetNames[i],gain=armGain,beforeDeg=angle,afterDeg=angle*armGain,elbowShiftM=Vector3.Distance(elbow,tb[i+1].position),handShiftM=Vector3.Distance(hand,tb[i+2].position)};lastArmTwistProof.Add(proof);if(proof.elbowShiftM>1e-6f||proof.handShiftM>1e-6f)throw new Exception("Twist-only upper-arm endpoint gate >1um");}}
